function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 20) return 'matrix needs 1 to 20 rows.';
  const width = Array.isArray(matrix[0]) ? matrix[0].length : 0;
  if (width < 1 || width > 20) return 'Each row needs 1 to 20 values.';
  if (matrix.some(row => !Array.isArray(row) || row.length !== width)) return 'All rows must have the same length.';
  if (matrix.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 99))) return 'Each value is an integer from 0 to 99.';
  return null;
}

