function isToeplitzMatrix(matrix) {
  // Collect every diagonal's values under its key row - col, then require one distinct value per diagonal.
  const diagonals = new Map();
  matrix.forEach((values, r) => values.forEach((v, c) => {
    if (!diagonals.has(r - c)) diagonals.set(r - c, new Set());
    diagonals.get(r - c).add(v);
  }));
  return [...diagonals.values()].every(set => set.size === 1);
}

