function generate(rand, size) {
  const large = size === 'large';
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = large ? int(15, 20) : int(1, 5);
  const n = large ? int(15, 20) : int(1, 5);
  const top = large ? 99 : 3;
  // Build a Toeplitz matrix from its first row and first column, then maybe break one diagonal.
  const firstRow = Array.from({ length: n }, () => int(0, top));
  const firstCol = Array.from({ length: m }, (_, r) => (r === 0 ? firstRow[0] : int(0, top)));
  const matrix = Array.from({ length: m }, (_, r) => Array.from({ length: n }, (_, c) => (r >= c ? firstCol[r - c] : firstRow[c - r])));
  if (rand() < 0.5) {
    const r = int(0, m - 1), c = int(0, n - 1);
    matrix[r][c] = int(0, top);
  }
  return [matrix];
}
